import os
from rich.console import Console
from rich.panel import Panel

console = Console()

def read_source_file(file_path: str) -> str:
    """Reads a local file to be processed by the AI pipeline."""
    if not os.path.exists(file_path):
        raise FileNotFoundError(f"Target file not found at: {file_path}")
    with open(file_path, "r", encoding="utf-8") as f:
        return f.read()

def write_output_file(file_path: str, content: str):
    """Writes the production-ready code generated by Claude Opus 5.5."""
    os.makedirs(os.path.dirname(os.path.abspath(file_path)), exist_ok=True)
    with open(file_path, "w", encoding="utf-8") as f:
        f.write(content)

def log_step(title: str, subtitle: str, style: str = "bold cyan"):
    """Displays polished terminal separation logs."""
    console.print(Panel(subtitle, title=title, border_style=style))
